package com.afkstarminer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AFKStarMinerConfig.CONFIG_GROUP)
public interface AFKStarMinerConfig extends Config
{
	String CONFIG_GROUP = "afk-star-miner";

	@Range(
		min = 0,
		max = 90
	)
	@Units(Units.PERCENT)
	@ConfigItem(
		keyName = "screenDarkness",
		name = "Screen darkness",
		description = "Opacity of the black overlay while mining a crashed star",
		position = 0
	)
	default int screenDarkness()
	{
		return 55;
	}

	@ConfigItem(
		keyName = "completionSound",
		name = "Completion sound",
		description = "Play the selected sound when the current layer timer reaches zero",
		position = 1
	)
	default boolean completionSound()
	{
		return true;
	}

	@ConfigItem(
		keyName = "completionSoundEffect",
		name = "Completion sound effect",
		description = "Sound played at layer completion; selecting a sound plays a preview",
		position = 2
	)
	default StarCompletionSound completionSoundEffect()
	{
		return StarCompletionSound.DIVINE_TINK;
	}

	@ConfigItem(
		keyName = "starOutlineColor",
		name = "Star outline color",
		description = "Color used for the crashed-star outline and tier label",
		position = 3
	)
	default Color starOutlineColor()
	{
		return new Color(255, 215, 0);
	}
}

package com.afkstarminer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class AFKStarMinerOverlay extends Overlay
{
	private static final Color TIMER_COLOR = Color.WHITE;
	private static final Color LEVEL_COLOR = new Color(215, 215, 215);
	private static final Color TEXT_SHADOW = new Color(0, 0, 0, 220);

	private final Client client;
	private final AFKStarMinerPlugin plugin;
	private final AFKStarMinerConfig config;

	@Inject
	AFKStarMinerOverlay(Client client, AFKStarMinerPlugin plugin, AFKStarMinerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.getGameState() != GameState.LOGGED_IN || !plugin.shouldShowOverlay())
		{
			return null;
		}

		int width = client.getCanvasWidth();
		int height = client.getCanvasHeight();
		Graphics2D overlayGraphics = (Graphics2D) graphics.create();
		try
		{
			overlayGraphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			int alpha = Math.round(255 * config.screenDarkness() / 100.0f);
			overlayGraphics.setColor(new Color(0, 0, 0, alpha));
			overlayGraphics.fillRect(0, 0, width, height);

			String levelText = "Level " + plugin.getStarTier();
			String timerText = plugin.getEstimatedLayerRemainingMillis() < 0L
				? "-- MIN -- SEC"
				: StarLayerTimer.format(plugin.getEstimatedLayerRemainingMillis());

			Font levelFont = FontManager.getDefaultBoldFont().deriveFont(Font.BOLD, 30.0f);
			Font timerFont = FontManager.getDefaultBoldFont().deriveFont(Font.BOLD, 52.0f);
			int centerY = height / 2;

			drawCenteredText(overlayGraphics, levelText, levelFont, LEVEL_COLOR, width, centerY - 32);
			drawCenteredText(overlayGraphics, timerText, timerFont, TIMER_COLOR, width, centerY + 38);
		}
		finally
		{
			overlayGraphics.dispose();
		}

		return null;
	}

	private static void drawCenteredText(Graphics2D graphics, String text, Font font,
		Color color, int width, int baseline)
	{
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		int x = (width - metrics.stringWidth(text)) / 2;
		graphics.setColor(TEXT_SHADOW);
		graphics.drawString(text, x + 2, baseline + 2);
		graphics.setColor(color);
		graphics.drawString(text, x, baseline);
	}
}

package com.afkstarminer;

import com.google.inject.Provides;
import java.io.IOException;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.SoundEffectVolume;
import net.runelite.api.Tile;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "AFK Star Miner",
	description = "Shows a dimmed layer timer, star tier, outline, and completion sound while mining crashed stars",
	tags = {"mining", "shooting star", "star", "afk", "timer", "overlay", "notification"},
	internalName = "afk-star-miner"
)
public class AFKStarMinerPlugin extends Plugin
{
	private static final int STAR_MINER_DISTANCE = 4;
	private static final int DESPAWN_GRACE_TICKS = 2;
	private static final int COMPLETION_MINING_GRACE_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private AudioPlayer audioPlayer;

	@Inject
	private ScheduledExecutorService executorService;

	@Inject
	private AFKStarMinerConfig config;

	@Inject
	private AFKStarMinerOverlay overlay;

	@Inject
	private AFKStarMinerStarOverlay starOverlay;

	@Inject
	private AFKStarMinerTierOverlay tierOverlay;

	@Inject
	private OverlayManager overlayManager;

	private GameObject starObject;
	private WorldPoint starLocation;
	private NPC starHeadbar;
	private int starTier;
	private long estimatedLayerRemainingMillis;
	private double lastHealthFraction;
	private boolean awaitingLayerReset;
	private boolean sceneScanPending;
	private boolean localPlayerMiningStar;
	private boolean completionSoundPlayed;
	private int lastLocalMiningTick;
	private int despawnTick;
	private WorldPoint despawnedLocation;

	@Override
	protected void startUp()
	{
		resetStar();
		sceneScanPending = true;
		overlayManager.add(starOverlay);
		overlayManager.add(overlay);
		overlayManager.add(tierOverlay);
		log.debug("AFK Star Miner started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(tierOverlay);
		overlayManager.remove(starOverlay);
		overlayManager.remove(overlay);
		resetStar();
		log.debug("AFK Star Miner stopped");
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		int tier = CrashedStarTier.fromObjectId(event.getGameObject().getId());
		if (tier > 0)
		{
			trackStar(event.getGameObject(), tier);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (starObject == null || event.getGameObject() != starObject)
		{
			return;
		}

		if (wasMiningStarRecently())
		{
			estimatedLayerRemainingMillis = 0L;
			playCompletionSoundOnce();
		}

		starObject = null;
		localPlayerMiningStar = false;
		despawnTick = client.getTickCount();
		despawnedLocation = starLocation;
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() == client.getLocalPlayer())
		{
			updateLocalMiningState();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!AFKStarMinerConfig.CONFIG_GROUP.equals(event.getGroup())
			|| !"completionSoundEffect".equals(event.getKey()))
		{
			return;
		}

		playSound(config.completionSoundEffect());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (npc.getId() == NpcID.STAR_HEADBAR_NPC && isAtTrackedStar(npc.getWorldLocation()))
		{
			starHeadbar = npc;
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (event.getNpc() == starHeadbar)
		{
			starHeadbar = null;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			sceneScanPending = true;
			return;
		}

		if (event.getGameState() == GameState.HOPPING
			|| event.getGameState() == GameState.LOGGING_IN
			|| event.getGameState() == GameState.LOGIN_SCREEN)
		{
			resetStar();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		if (sceneScanPending)
		{
			sceneScanPending = false;
			scanSceneForStar();
		}

		if (starObject == null && despawnedLocation != null
			&& client.getTickCount() - despawnTick >= DESPAWN_GRACE_TICKS)
		{
			resetStar();
			return;
		}

		if (starObject == null)
		{
			return;
		}

		if (starHeadbar == null)
		{
			starHeadbar = findHeadbar();
		}

		updateLocalMiningState();
		if (wasMiningStarRecently())
		{
			updateLayerEstimate();
		}
	}

	private void trackStar(GameObject gameObject, int tier)
	{
		WorldPoint location = gameObject.getWorldLocation();
		boolean sameStar = starLocation != null && starLocation.equals(location);
		boolean layerChanged = sameStar && starTier > 0 && tier != starTier;

		if (layerChanged && wasMiningStarRecently())
		{
			estimatedLayerRemainingMillis = 0L;
			playCompletionSoundOnce();
		}

		starObject = gameObject;
		starLocation = location;
		starTier = tier;
		despawnedLocation = null;

		if (!sameStar)
		{
			estimatedLayerRemainingMillis = -1L;
			lastHealthFraction = -1.0;
			awaitingLayerReset = false;
			completionSoundPlayed = false;
			lastLocalMiningTick = -1;
			starHeadbar = findHeadbar();
		}
		else if (layerChanged)
		{
			estimatedLayerRemainingMillis = StarLayerTimer.LAYER_DURATION_MILLIS;
			awaitingLayerReset = true;
			completionSoundPlayed = false;
		}

		updateLocalMiningState();
	}

	private void updateLayerEstimate()
	{
		double healthFraction = getHealthFraction();
		if (healthFraction >= 0.0)
		{
			if (awaitingLayerReset && lastHealthFraction >= 0.0
				&& healthFraction <= lastHealthFraction)
			{
				decrementLayerEstimate();
				return;
			}

			awaitingLayerReset = false;
			if (Double.compare(healthFraction, lastHealthFraction) != 0)
			{
				estimatedLayerRemainingMillis = StarLayerTimer.remainingMillis(healthFraction);
				lastHealthFraction = healthFraction;
				playCompletionSoundIfTimerFinished();
				return;
			}
		}

		decrementLayerEstimate();
	}

	private void decrementLayerEstimate()
	{
		if (estimatedLayerRemainingMillis < 0L)
		{
			return;
		}

		estimatedLayerRemainingMillis = Math.max(0L,
			estimatedLayerRemainingMillis - Constants.GAME_TICK_LENGTH);
		playCompletionSoundIfTimerFinished();
	}

	private double getHealthFraction()
	{
		if (starHeadbar == null || starHeadbar.getHealthRatio() < 0 || starHeadbar.getHealthScale() <= 0)
		{
			return -1.0;
		}

		return Math.min(1.0, Math.max(0.0,
			starHeadbar.getHealthRatio() / (double) starHeadbar.getHealthScale()));
	}

	private void updateLocalMiningState()
	{
		Player localPlayer = client.getLocalPlayer();
		localPlayerMiningStar = starObject != null
			&& starLocation != null
			&& localPlayer != null
			&& StarMiningAnimations.contains(localPlayer.getAnimation())
			&& localPlayer.getWorldLocation().distanceTo(starLocation) <= STAR_MINER_DISTANCE;

		if (localPlayerMiningStar)
		{
			lastLocalMiningTick = client.getTickCount();
		}
	}

	private boolean wasMiningStarRecently()
	{
		return localPlayerMiningStar
			|| lastLocalMiningTick >= 0
			&& client.getTickCount() - lastLocalMiningTick <= COMPLETION_MINING_GRACE_TICKS;
	}

	private void playCompletionSoundIfTimerFinished()
	{
		if (estimatedLayerRemainingMillis == 0L)
		{
			playCompletionSoundOnce();
		}
	}

	private void playCompletionSoundOnce()
	{
		if (!completionSoundPlayed && config.completionSound())
		{
			playSound(config.completionSoundEffect());
		}
		completionSoundPlayed = true;
	}

	private void playSound(StarCompletionSound sound)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			if (!sound.isCustom())
			{
				client.playSoundEffect(sound.getSoundEffectId());
				return;
			}

			int volume = client.getPreferences().getSoundEffectVolume();
			if (volume <= SoundEffectVolume.MUTED)
			{
				return;
			}

			float gain = (float) (20.0 * Math.log10(
				Math.min(volume, SoundEffectVolume.HIGH) / (double) SoundEffectVolume.HIGH));
			executorService.execute(() -> playCustomSound(sound, gain));
		});
	}

	private void playCustomSound(StarCompletionSound sound, float gain)
	{
		try
		{
			audioPlayer.play(AFKStarMinerPlugin.class, sound.getResourcePath(), gain);
		}
		catch (IOException | UnsupportedAudioFileException | LineUnavailableException ex)
		{
			log.warn("Unable to play custom completion sound", ex);
		}
	}

	private NPC findHeadbar()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (starLocation == null || worldView == null)
		{
			return null;
		}

		for (NPC npc : worldView.npcs())
		{
			if (npc.getId() == NpcID.STAR_HEADBAR_NPC && starLocation.equals(npc.getWorldLocation()))
			{
				return npc;
			}
		}
		return null;
	}

	private void scanSceneForStar()
	{
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		Scene scene = worldView.getScene();
		Tile[][] tiles = scene.getTiles()[worldView.getPlane()];
		for (Tile[] row : tiles)
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}

				for (GameObject gameObject : tile.getGameObjects())
				{
					if (gameObject == null)
					{
						continue;
					}

					int tier = CrashedStarTier.fromObjectId(gameObject.getId());
					if (tier > 0)
					{
						trackStar(gameObject, tier);
						return;
					}
				}
			}
		}
	}

	private boolean isAtTrackedStar(WorldPoint location)
	{
		return starLocation != null && starLocation.equals(location);
	}

	private void resetStar()
	{
		starObject = null;
		starLocation = null;
		starHeadbar = null;
		starTier = 0;
		estimatedLayerRemainingMillis = -1L;
		lastHealthFraction = -1.0;
		awaitingLayerReset = false;
		localPlayerMiningStar = false;
		completionSoundPlayed = false;
		lastLocalMiningTick = -1;
		despawnTick = 0;
		despawnedLocation = null;
	}

	boolean shouldShowOverlay()
	{
		return starTier > 0 && starObject != null && localPlayerMiningStar;
	}

	int getStarTier()
	{
		return starTier;
	}

	long getEstimatedLayerRemainingMillis()
	{
		return estimatedLayerRemainingMillis;
	}

	GameObject getStarObject()
	{
		return starObject;
	}

	@Provides
	AFKStarMinerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AFKStarMinerConfig.class);
	}
}

package com.afkstarminer;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class AFKStarMinerStarOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 4;
	private static final int OUTLINE_FEATHER = 1;

	private final Client client;
	private final AFKStarMinerPlugin plugin;
	private final AFKStarMinerConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	AFKStarMinerStarOverlay(Client client, AFKStarMinerPlugin plugin, AFKStarMinerConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GameObject star = plugin.getStarObject();
		if (client.getGameState() != GameState.LOGGED_IN || star == null || plugin.getStarTier() <= 0)
		{
			return null;
		}

		modelOutlineRenderer.drawOutline(star, OUTLINE_WIDTH, config.starOutlineColor(), OUTLINE_FEATHER);
		return null;
	}
}

package com.afkstarminer;

import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

class AFKStarMinerTierOverlay extends Overlay
{
	private static final int LABEL_HEIGHT = 150;

	private final Client client;
	private final AFKStarMinerPlugin plugin;
	private final AFKStarMinerConfig config;

	@Inject
	AFKStarMinerTierOverlay(Client client, AFKStarMinerPlugin plugin, AFKStarMinerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(Overlay.PRIORITY_HIGHEST);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		GameObject star = plugin.getStarObject();
		if (client.getGameState() != GameState.LOGGED_IN || star == null || plugin.getStarTier() <= 0)
		{
			return null;
		}

		String tierText = "T" + plugin.getStarTier();
		Graphics2D textGraphics = (Graphics2D) graphics.create();
		try
		{
			textGraphics.setFont(FontManager.getDefaultBoldFont().deriveFont(Font.BOLD, 20.0f));
			Point textLocation = star.getCanvasTextLocation(textGraphics, tierText, LABEL_HEIGHT);
			if (textLocation != null)
			{
				OverlayUtil.renderTextLocation(textGraphics, textLocation, tierText, config.starOutlineColor());
			}
		}
		finally
		{
			textGraphics.dispose();
		}

		return null;
	}
}

package com.afkstarminer;

final class CrashedStarTier
{
	// RuneLite gameval does not currently expose the crashed-star object IDs.
	static final int TIER_1_OBJECT_ID = 41229;
	static final int TIER_2_OBJECT_ID = 41228;
	static final int TIER_3_OBJECT_ID = 41227;
	static final int TIER_4_OBJECT_ID = 41226;
	static final int TIER_5_OBJECT_ID = 41225;
	static final int TIER_6_OBJECT_ID = 41224;
	static final int TIER_7_OBJECT_ID = 41223;
	static final int TIER_8_OBJECT_ID = 41021;
	static final int TIER_9_OBJECT_ID = 41020;

	private CrashedStarTier()
	{
	}

	static int fromObjectId(int objectId)
	{
		switch (objectId)
		{
			case TIER_1_OBJECT_ID:
				return 1;
			case TIER_2_OBJECT_ID:
				return 2;
			case TIER_3_OBJECT_ID:
				return 3;
			case TIER_4_OBJECT_ID:
				return 4;
			case TIER_5_OBJECT_ID:
				return 5;
			case TIER_6_OBJECT_ID:
				return 6;
			case TIER_7_OBJECT_ID:
				return 7;
			case TIER_8_OBJECT_ID:
				return 8;
			case TIER_9_OBJECT_ID:
				return 9;
			default:
				return 0;
		}
	}
}

package com.afkstarminer;

import net.runelite.api.SoundEffectID;

public enum StarCompletionSound
{
	DIVINE_TINK("Divine-style tink", "/sounds/divine_tink.wav"),
	BELL_DING("Bell ding", SoundEffectID.TOWN_CRIER_BELL_DING),
	BELL_DONG("Bell dong", SoundEffectID.TOWN_CRIER_BELL_DONG),
	GRAND_EXCHANGE_DING("Grand Exchange ding", SoundEffectID.GE_ADD_OFFER_DINGALING),
	COIN_TINKLE("Coin tinkle", SoundEffectID.GE_COIN_TINKLE),
	UI_BOOP("UI boop", SoundEffectID.UI_BOOP),
	MINING_TINK("Mining tink", SoundEffectID.MINING_TINK),
	TELEPORT("Teleport", SoundEffectID.TELEPORT_VWOOP);

	private final String displayName;
	private final int soundEffectId;
	private final String resourcePath;

	StarCompletionSound(String displayName, int soundEffectId)
	{
		this.displayName = displayName;
		this.soundEffectId = soundEffectId;
		this.resourcePath = null;
	}

	StarCompletionSound(String displayName, String resourcePath)
	{
