package com.afkstarminer;

import java.time.Duration;

final class StarLayerTimer
{
	static final long LAYER_DURATION_MILLIS = Duration.ofMinutes(7).toMillis();

	private StarLayerTimer()
	{
	}

	static long remainingMillis(double layerRemainingFraction)
	{
		double fraction = Math.min(1.0, Math.max(0.0, layerRemainingFraction));
		return Math.round(fraction * LAYER_DURATION_MILLIS);
	}

	static String format(long remainingMillis)
	{
		long totalSeconds = Math.max(0L, (remainingMillis + 999L) / 1_000L);
		long minutes = totalSeconds / 60L;
		long seconds = totalSeconds % 60L;
		return String.format("%d MIN %02d SEC", minutes, seconds);
	}
}

